@using sv_09cd24003e184447b8b591adbedafdd7.Models
@using sv_09cd24003e184447b8b591adbedafdd7.Services
@inject ISettingsService SettingsService

<h4 class="mb-4">Profile</h4>

@if (_loading)
{
    <p class="text-muted">Loading profile…</p>
    return;
}

@if (_successMessage is not null)
{
    <div class="alert alert-success alert-dismissible" role="alert">
        @_successMessage
        <button type="button" class="btn-close" @onclick="() => _successMessage = null"></button>
    </div>
}

<div class="row mb-4">
    <div class="col-md-3 text-center">
        <img src="@_avatarUrl" alt="Avatar" class="rounded-circle mb-2" width="100" height="100"
             onerror="this.src='https://via.placeholder.com/100'" />
        <div class="text-muted small text-break">@_avatarUrl</div>
    </div>
    <div class="col-md-9">
        <div class="mb-3">
            <label class="form-label">Display Name</label>
            <input type="text" class="form-control" @bind="_displayName" />
        </div>
        <div class="mb-3">
            <label class="form-label">Email</label>
            <input type="email" class="form-control" @bind="_email" />
        </div>
        <div class="mb-3">
            <label class="form-label">Avatar URL</label>
            <input type="url" class="form-control" @bind="_avatarUrl" />
        </div>
        <div class="mb-3">
            <label class="form-label">Bio</label>
            <textarea class="form-control" rows="3" @bind="_bio"></textarea>
        </div>
    </div>
</div>

<div class="d-flex gap-2">
    <button class="btn btn-primary" @onclick="SaveChanges" disabled="@_saving">
        @(_saving ? "Saving…" : "Save Changes")
    </button>
    <button class="btn btn-outline-secondary" @onclick="DiscardChanges">Discard Changes</button>
</div>

@code {
    private string _displayName = "";
    private string _email = "";
    private string _avatarUrl = "";
    private string _bio = "";
    private UserProfile? _savedProfile;
    private bool _loading = true;
    private bool _saving;
    private string? _successMessage;

    protected override async Task OnInitializedAsync()
    {
        var profile = await SettingsService.GetProfileAsync();
        _savedProfile = profile;
        ApplyProfile(profile);
        _loading = false;
    }

    private void ApplyProfile(UserProfile p)
    {
        _displayName = p.DisplayName;
        _email = p.Email;
        _avatarUrl = p.AvatarUrl;
        _bio = p.Bio;
    }

    private async Task SaveChanges()
    {
        _saving = true;
        var profile = new UserProfile(_displayName, _email, _avatarUrl, _bio);
        await SettingsService.SaveProfileAsync(profile);
        _savedProfile = profile;
        _successMessage = "Profile saved successfully!";
        _saving = false;
    }

    private void DiscardChanges()
    {
        if (_savedProfile is not null)
        {
            ApplyProfile(_savedProfile);
        }
        _successMessage = null;
    }
}

@using sv_09cd24003e184447b8b591adbedafdd7.Models
@using sv_09cd24003e184447b8b591adbedafdd7.Services
@inject ISettingsService SettingsService

<h4 class="mb-4">Notifications</h4>

@if (_loading)
{
    <p class="text-muted">Loading notification preferences…</p>
    return;
}

@if (_successMessage is not null)
{
    <div class="alert alert-success alert-dismissible" role="alert">
        @_successMessage
        <button type="button" class="btn-close" @onclick="() => _successMessage = null"></button>
    </div>
}

<div class="mb-4">
    <h6>General</h6>
    <div class="form-check form-switch mb-2">
        <input class="form-check-input" type="checkbox" role="switch" id="emailNotif"
               checked="@_emailNotifications" @onchange="e => _emailNotifications = (bool)e.Value!" />
        <label class="form-check-label" for="emailNotif">Email Notifications</label>
    </div>
    <div class="form-check form-switch mb-2">
        <input class="form-check-input" type="checkbox" role="switch" id="pushNotif"
               checked="@_pushNotifications" @onchange="e => _pushNotifications = (bool)e.Value!" />
        <label class="form-check-label" for="pushNotif">Push Notifications</label>
    </div>
    <div class="form-check form-switch mb-2">
        <input class="form-check-input" type="checkbox" role="switch" id="weeklyDigest"
               checked="@_weeklyDigest" @onchange="e => _weeklyDigest = (bool)e.Value!" />
        <label class="form-check-label" for="weeklyDigest">Weekly Digest</label>
    </div>
</div>

<div class="mb-4">
    <h6>Muted Channels</h6>
    @foreach (var channel in AllChannels)
    {
        var isMuted = _mutedChannels.Contains(channel);
        <div class="form-check mb-1">
            <input class="form-check-input" type="checkbox" id="@($"ch-{channel}")"
                   checked="@isMuted"
                   @onchange="e => ToggleMute(channel, (bool)e.Value!)" />
            <label class="form-check-label" for="@($"ch-{channel}")">
                #@channel @(isMuted ? "(muted)" : "")
            </label>
        </div>
    }
</div>

<button class="btn btn-primary" @onclick="SavePreferences" disabled="@_saving">
    @(_saving ? "Saving…" : "Save Preferences")
</button>

@code {
    private static readonly string[] AllChannels =
        ["general", "announcements", "random", "engineering", "design", "support"];

    private bool _emailNotifications;
    private bool _pushNotifications;
    private bool _weeklyDigest;
    private HashSet<string> _mutedChannels = [];
    private bool _loading = true;
    private bool _saving;
    private string? _successMessage;

    protected override async Task OnInitializedAsync()
    {
        var prefs = await SettingsService.GetNotificationPrefsAsync();
        _emailNotifications = prefs.EmailNotifications;
        _pushNotifications = prefs.PushNotifications;
        _weeklyDigest = prefs.WeeklyDigest;
        _mutedChannels = [.. prefs.MutedChannels];
        _loading = false;
    }

    private void ToggleMute(string channel, bool muted)
    {
        if (muted) _mutedChannels.Add(channel);
        else _mutedChannels.Remove(channel);
    }

    private async Task SavePreferences()
    {
        _saving = true;
        var prefs = new NotificationPrefs(
            _emailNotifications, _pushNotifications, _weeklyDigest,
            _mutedChannels.ToList());
        await SettingsService.SaveNotificationPrefsAsync(prefs);
        _successMessage = "Notification preferences saved!";
        _saving = false;
    }
}

@using sv_09cd24003e184447b8b591adbedafdd7.Models
@using sv_09cd24003e184447b8b591adbedafdd7.Services
@inject ISettingsService SettingsService

<h4 class="mb-4">Security</h4>

@if (_loading)
{
