+        <div class="form-check form-switch">
+            <input class="form-check-input" type="checkbox" role="switch" id="twoFactor"
+                   checked="@_twoFactorEnabled" @onchange="e => _twoFactorEnabled = (bool)e.Value!" />
+            <label class="form-check-label" for="twoFactor">Enable 2FA</label>
+        </div>
+        <span class="badge @(_twoFactorEnabled ? "bg-success" : "bg-secondary")">
+            @(_twoFactorEnabled ? "Enabled" : "Disabled")
+        </span>
+    </div>
+    @if (_lastPasswordChange.HasValue)
+    {
+        <small class="text-muted d-block mt-2">
+            Last password change: @_lastPasswordChange.Value.ToString("MMMM d, yyyy")
+        </small>
+    }
+</div>
+
+<div class="mb-4">
+    <h6>Active Sessions</h6>
+    <div class="table-responsive">
+        <table class="table table-hover align-middle">
+            <thead>
+                <tr>
+                    <th>Device</th>
+                    <th>Location</th>
+                    <th>Last Active</th>
+                    <th></th>
+                </tr>
+            </thead>
+            <tbody>
+                @foreach (var session in _sessions)
+                {
+                    var isCurrent = session.Id == _sessions.FirstOrDefault()?.Id;
+                    <tr>
+                        <td>
+                            @session.Device
+                            @if (isCurrent)
+                            {
+                                <span class="badge bg-info ms-1">Current</span>
+                            }
+                        </td>
+                        <td>@session.Location</td>
+                        <td>@FormatLastActive(session.LastActive)</td>
+                        <td>
+                            @if (!isCurrent)
+                            {
+                                <button class="btn btn-sm btn-outline-danger"
+                                        @onclick="() => PromptRevoke(session)">
+                                    Revoke
+                                </button>
+                            }
+                        </td>
+                    </tr>
+                }
+            </tbody>
+        </table>
+    </div>
+</div>
+
+<RevokeSessionDialog Visible="_showRevokeDialog"
+                     Session="_sessionToRevoke"
+                     OnConfirm="ConfirmRevoke"
+                     OnCancel="CancelRevoke" />
+
+@code {
+    private bool _loading = true;
+    private bool _twoFactorEnabled;
+    private DateTime? _lastPasswordChange;
+    private List<ActiveSession> _sessions = [];
+    private bool _showRevokeDialog;
+    private ActiveSession? _sessionToRevoke;
+
+    protected override async Task OnInitializedAsync()
+    {
+        await LoadSettings();
+        _loading = false;
+    }
+
+    private async Task LoadSettings()
+    {
+        var settings = await SettingsService.GetSecuritySettingsAsync();
+        _twoFactorEnabled = settings.TwoFactorEnabled;
+        _lastPasswordChange = settings.LastPasswordChange;
+        _sessions = settings.Sessions.ToList();
+    }
+
+    private async Task HandleChangePassword((string Current, string New) args)
+    {
+        await SettingsService.ChangePasswordAsync(args.Current, args.New);
+        await LoadSettings();
+    }
+
+    private void PromptRevoke(ActiveSession session)
+    {
+        _sessionToRevoke = session;
+        _showRevokeDialog = true;
+    }
+
+    private async Task ConfirmRevoke()
+    {
+        if (_sessionToRevoke is not null)
+        {
+            await SettingsService.RevokeSessionAsync(_sessionToRevoke.Id);
+            await LoadSettings();
+        }
+        _showRevokeDialog = false;
+        _sessionToRevoke = null;
+    }
+
+    private void CancelRevoke()
+    {
+        _showRevokeDialog = false;
+        _sessionToRevoke = null;
+    }
+
+    private static string FormatLastActive(DateTime dt)
+    {
+        var diff = DateTime.UtcNow - dt;
+        if (diff.TotalMinutes < 1) return "Just now";
+        if (diff.TotalMinutes < 60) return $"{(int)diff.TotalMinutes}m ago";
+        if (diff.TotalHours < 24) return $"{(int)diff.TotalHours}h ago";
+        return $"{(int)diff.TotalDays}d ago";
+    }
+}
+

toolArgs.file_text:
@using sv_09cd24003e184447b8b591adbedafdd7.Models
@using sv_09cd24003e184447b8b591adbedafdd7.Services
@inject ISettingsService SettingsService

<h4 class="mb-4">Appearance</h4>

@if (_loading)
{
    <p class="text-muted">Loading appearance settings…</p>
    return;
}

@if (_successMessage is not null)
{
    <div class="alert alert-success alert-dismissible" role="alert">
        @_successMessage
        <button type="button" class="btn-close" @onclick="() => _successMessage = null"></button>
    </div>
}

<div class="row">
    <div class="col-md-7">
        <div class="mb-4">
            <h6>Theme</h6>
            @foreach (var theme in new[] { "Light", "Dark", "System" })
            {
                <div class="form-check">
                    <input class="form-check-input" type="radio" name="theme" id="@($"theme-{theme}")"
                           value="@theme" checked="@(_theme == theme)"
                           @onchange="() => _theme = theme" />
                    <label class="form-check-label" for="@($"theme-{theme}")">@theme</label>
                </div>
            }
        </div>

        <div class="mb-4">
            <h6>Font Size</h6>
            @foreach (var size in new[] { "Small", "Medium", "Large" })
            {
                <div class="form-check">
                    <input class="form-check-input" type="radio" name="fontSize" id="@($"fs-{size}")"
                           value="@size" checked="@(_fontSize == size)"
                           @onchange="() => _fontSize = size" />
                    <label class="form-check-label" for="@($"fs-{size}")">@size</label>
                </div>
            }
        </div>

        <div class="mb-4">
            <h6>Language</h6>
            <select class="form-select" style="max-width: 250px" @bind="_language">
                @foreach (var lang in Languages)
                {
                    <option value="@lang">@lang</option>
                }
            </select>
        </div>

        <div class="mb-4">
            <h6>Compact Mode</h6>
            <div class="form-check form-switch">
                <input class="form-check-input" type="checkbox" role="switch" id="compactMode"
                       checked="@_compactMode" @onchange="e => _compactMode = (bool)e.Value!" />
                <label class="form-check-label" for="compactMode">Enable compact layout</label>
            </div>
        </div>

        <button class="btn btn-primary" @onclick="SaveAppearance" disabled="@_saving">
            @(_saving ? "Saving…" : "Save")
        </button>
    </div>

    <div class="col-md-5">
        <h6>Preview</h6>
        <div class="border rounded @PreviewBgClass" style="@PreviewStyle">
            <div class="@PreviewPadding">
                <div class="fw-bold mb-1" style="@PreviewFontStyle">Sample Heading</div>
                <p class="mb-2" style="@PreviewFontStyle">
                    This is a preview of how your content will look with the selected settings.
                </p>
                <div class="d-flex gap-2">
                    <span class="badge @PreviewBadgeClass">Badge</span>
                    <button class="btn btn-sm @PreviewBtnClass" disabled>Button</button>
                </div>
                <div class="mt-2">
                    <small class="text-muted">
                        Theme: @_theme · Font: @_fontSize · Lang: @_language · Compact: @(_compactMode ? "On" : "Off")
                    </small>
                </div>
            </div>
        </div>
    </div>
</div>

@code {
    private static readonly string[] Languages = ["English", "Spanish", "French", "German", "Japanese", "Chinese"];

    private string _theme = "Light";
    private string _fontSize = "Medium";
    private string _language = "English";
    private bool _compactMode;
    private bool _loading = true;
    private bool _saving;
    private string? _successMessage;

    protected override async Task OnInitializedAsync()
    {
        var settings = await SettingsService.GetAppearanceAsync();
        _theme = settings.Theme;
        _fontSize = settings.FontSize;
        _language = settings.Language;
        _compactMode = settings.CompactMode;
        _loading = false;
    }

    private async Task SaveAppearance()
    {
        _saving = true;
        await SettingsService.SaveAppearanceAsync(
            new AppearanceSettings(_theme, _fontSize, _language, _compactMode));
        _successMessage = "Appearance settings saved!";
        _saving = false;
    }

    // Live preview computed properties
    private string PreviewBgClass => _theme switch
    {
        "Dark" => "bg-dark text-light",
        _ => "bg-light text-dark"
    };

    private string PreviewStyle => _theme == "Dark"
        ? "min-height: 180px; border-color: #495057 !important;"
        : "min-height: 180px;";

    private string PreviewFontStyle => _fontSize switch
    {
        "Small" => "font-size: 0.8rem;",
        "Large" => "font-size: 1.2rem;",
        _ => "font-size: 1rem;"
    };

    private string PreviewPadding => _compactMode ? "p-2" : "p-3";

    private string PreviewBadgeClass => _theme == "Dark" ? "bg-light text-dark" : "bg-primary";

    private string PreviewBtnClass => _theme == "Dark" ? "btn-outline-light" : "btn-outline-primary";
}

